import copy
import json
import os
import sys

import pytest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))

from steps import extraction_validator as V  # noqa: E402
from steps import extractors  # noqa: E402
from steps import step_03_resolver as r3  # noqa: E402

DOC = "\n".join([
    "<!-- generated by batch_extract_with_claude.py via pdfplumber -->",
    "",
    "<!-- page 3 -->",
    "Table 5. DC Characteristics",
    "PARAMETER SYMBOL MIN TYP MAX UNIT",
    "High-level input voltage VIH 2.0 V",
    "Low-level input voltage VIL 0.8 V",
    "Input high voltage V 1.7 V",
    "IH",
    "Supply voltage VCC 2.7 3.3 3.6 V",
    "Input voltage range VIN VCC+0.3 V",
    "RESET pin input high voltage 2.2 V",
])


def group(**kw):
    g = {"group_name": "IO", "pin_type": "digital_input", "example_pins": ["PA0"], "applies_to": "inputs"}
    for f in V.NUMERIC:
        g[f] = None
    g.update(kw)
    return g


def run(groups, doc=DOC, default=None, source_text=None, stem="foo123"):
    raw = {"pin_groups": groups, "default_group": default}
    before = copy.deepcopy(raw)
    out, rep = V.validate(raw, model_input=doc, source_text=source_text, stem=stem)
    assert raw == before                                   # never mutates its input
    json.dumps(rep)                                        # the report is JSON-serialisable
    return out, rep


# ── 3a match classes ─────────────────────────────────────────────────────────
@pytest.mark.parametrize("quote,want", [
    ("High-level input voltage VIH 2.0 V", "verbatim"),
    ("High-level input voltage V IH 2.0 V extra-token-not-in-doc", "partial"),
    ("Logic threshold of the comparator 2.0", "foreign"),
])
def test_match_classes_numeric(quote, want):
    out, rep = run([group(VIH_min=2.0, quotes={"VIH_min": quote})])
    assert out["pin_groups"][0]["citations"]["VIH_min"]["match"] == want
    assert rep["match"][want] == 1


def test_match_layout_subscript_on_next_line():
    # "VIH" = adjacent window tokens "V" + "IH" (pdfplumber put the subscript on its own line)
    out, _ = run([group(VIH_min=1.7, quotes={"VIH_min": "Input high voltage VIH 1.7 V"})])
    assert out["pin_groups"][0]["citations"]["VIH_min"]["match"] == "layout"


def test_match_no_quote():
    out, rep = run([group(VIL_max=0.8)])
    assert out["pin_groups"][0]["citations"]["VIL_max"] == {
        "quote": None, "page": None, "section": None, "match": "no-quote"}
    assert rep["match"]["no-quote"] == 1


def test_page_and_section_derivation_and_source_keys():
    out, _ = run([group(VIH_min=2.0, absolute_max_voltage=None,
                        quotes={"VIH_min": "High-level input voltage VIH 2.0 V"})])
    g = out["pin_groups"][0]
    c = g["citations"]["VIH_min"]
    assert c["page"] == 3 and c["section"] == "Table 5. DC Characteristics"
    assert g["VIH_source"] == "Table 5. DC Characteristics"
    assert g["abs_max_source"] is None
    assert "quotes" not in g


def test_page_falls_back_to_source_text_for_a_markerless_slice():
    slice_text = "High-level input voltage VIH 2.0 V"
    source = "<!-- page 7 -->\nsome text\nHigh-level input voltage VIH 2.0 V"
    out, _ = run([group(VIH_min=2.0, quotes={"VIH_min": slice_text})], doc=slice_text, source_text=source)
    c = out["pin_groups"][0]["citations"]["VIH_min"]
    assert c["page"] == 7 and c["section"] is None
    assert out["pin_groups"][0]["VIH_source"] == "p. 7"


def test_sibling_fallback_derives_and_counts():
    out, rep = run([group(VIL_max=0.8, VOL_max=0.8, quotes={"VIL_max": "Low-level input voltage VIL 0.8 V"})])
    c = out["pin_groups"][0]["citations"]["VOL_max"]
    assert c["sibling"] == "VIL_max" and c["match"] == "verbatim"
    assert rep["counts"]["sibling_fallback"] == 1
    assert out["pin_groups"][0]["VOL_max"] == 0.8            # derivation only, no null rule on match


def test_alts_quotes_move_into_citations():
    alts = [{"condition": "VCC=3.3", "value": 2.0, "expr": None,
             "quote": "High-level input voltage VIH 2.0 V"}]
    out, _ = run([group(VIH_min_alts=alts)])
    g = out["pin_groups"][0]
    assert "quote" not in g["VIH_min_alts"][0]
    assert g["citations"]["VIH_min_alts[0]"]["match"] == "verbatim"


# ── 3b hard rules ────────────────────────────────────────────────────────────
def test_rule_a_nulls_an_expression_offset():
    out, rep = run([group(absolute_max_voltage=0.3, quotes={"absolute_max_voltage": "Input voltage range VIN VCC+0.3 V"})])
    g = out["pin_groups"][0]
    assert g["absolute_max_voltage"] is None
    assert g["citations"]["absolute_max_voltage"]["status"] == "nulled:a"
    assert g["citations"]["absolute_max_voltage"]["rejected_value"] == 0.3
    assert rep["counts"]["nulled_a"] == 1


def test_rule_f_nulls_a_wrong_column():
    out, rep = run([group(pin_type="power", example_pins=["VCC"],
                          supply_min=3.6, quotes={"supply_min": "Supply voltage VCC 2.7 3.3 3.6 V"})])
    g = out["pin_groups"][0]
    assert g["supply_min"] is None and g["citations"]["supply_min"]["status"] == "nulled:f"
    assert rep["counts"]["nulled_f"] == 1
    assert {"group": "IO", "index": 0, "field": "supply_min", "value": 3.6, "outcome": "NULLED",
            "a_fail": False} in rep["f_outcomes"]


def test_rule_f_right_column_binds():
    out, rep = run([group(pin_type="power", example_pins=["VCC"], supply_min=2.7, supply_max=3.6,
                          quotes={"supply_min": "Supply voltage VCC 2.7 3.3 3.6 V"})])
    g = out["pin_groups"][0]
    assert (g["supply_min"], g["supply_max"]) == (2.7, 3.6)
    assert {x["outcome"] for x in rep["f_outcomes"]} == {"PASS-BOUND"}


def test_rule_f_undecidable_passes():
    doc = "Supply voltage VCC 2.7 3.6 V"                      # two numbers, no MIN/TYP/MAX header
    out, rep = run([group(pin_type="power", example_pins=["VCC"], supply_min=3.6,
                          quotes={"supply_min": doc})], doc=doc)
    assert out["pin_groups"][0]["supply_min"] == 3.6
    assert rep["f_outcomes"][0]["outcome"] == "UNDECIDABLE" and rep["counts"]["nulled_f"] == 0


def test_no_window_passes():
    out, rep = run([group(VIH_min=9.9, quotes={"VIH_min": "VIH 9.9"})])
    assert out["pin_groups"][0]["VIH_min"] == 9.9
    assert rep["f_outcomes"][0]["outcome"] == "NO-WINDOW"


def test_rule_b_is_report_only():
    gs = [group(VIH_min=2.2, example_pins=["PA0"], quotes={"VIH_min": "RESET pin input high voltage 2.2 V"}),
          group(group_name="RST", example_pins=["RESET"])]
    out, rep = run(gs, doc="RESET pin input high voltage 2.2 V")
    assert out["pin_groups"][0]["VIH_min"] == 2.2
    assert rep["b_flags"] == [{"group": "IO", "field": "VIH_min", "value": 2.2}]


# ── 3c F4 coercions ──────────────────────────────────────────────────────────
def test_f4_bare_number_moved_or_dropped_and_railless_nulled():
    alts = [{"condition": "a", "value": None, "expr": "1.2+0.215"},
            {"condition": "b", "value": None, "expr": "0.7*VCC"}]
    out, rep = run([group(VIH_min_expr="1.24", VIL_max=0.4, VIL_max_expr="0.5",
                          VOH_min_expr="ADC_AVDD", VOL_max_expr="0.2*VCC", VIH_min_alts=alts)])
    g = out["pin_groups"][0]
    assert g["VIH_min"] == 1.24 and "VIH_min_expr" not in g
    assert g["VIL_max"] == 0.4 and "VIL_max_expr" not in g
    assert g["VOH_min_expr"] is None
    assert g["VOL_max_expr"] == "0.2*VCC"
    assert [a["expr"] for a in g["VIH_min_alts"]] == [None, "0.7*VCC"]
    c = rep["counts"]
    assert (c["expr_bare_coerced"], c["expr_bare_moved"], c["expr_bare_dropped"]) == (2, 1, 1)
    assert c["expr_railless_nulled"] == 2


# ── 3d post-filters ──────────────────────────────────────────────────────────
def test_retype_positive_on_example_pins_then_na_nulls_logic():
    out, rep = run([group(example_pins=["IOVDD"], supply_min=1.62, supply_max=3.63, VIH_min=0.952)])
    g = out["pin_groups"][0]
    assert g["pin_type"] == "power" and g["VIH_min"] is None and g["supply_min"] == 1.62
    assert rep["retyped"][0]["old_pin_type"] == "digital_input"


def test_retype_negative_group_name_and_rail_are_not_keys():
    out, rep = run([group(group_name="IOVDD GPIO", supply_rail_name="IOVDD", example_pins=["GPIO0"],
                          supply_min=1.62, VIH_min=0.952)])
    g = out["pin_groups"][0]
    assert g["pin_type"] == "digital_input" and g["supply_min"] is None and g["VIH_min"] == 0.952
    assert rep["counts"]["retyped"] == 0


def test_na_power_group_drops_logic_and_its_expr():
    out, _ = run([group(pin_type="power", example_pins=["VCC"], supply_max=3.6, VIH_min_expr="0.7*VCC")])
    g = out["pin_groups"][0]
    assert "VIH_min_expr" not in g and g["supply_max"] == 3.6


def test_na_ground_keeps_abs_max_only():
    out, _ = run([group(pin_type="power", example_pins=["GND"], supply_min=0.0, absolute_max_voltage=6.0)])
    g = out["pin_groups"][0]
    assert g["supply_min"] is None and g["absolute_max_voltage"] == 6.0


def test_na_ground_word_beside_a_supply_rail_is_not_ground():
    out, _ = run([group(group_name="Analog Power Supply VDDA/VSSA", pin_type="power",
                        example_pins=["VDDA", "VSSA"], supply_min=2.0, supply_max=3.6)])
    g = out["pin_groups"][0]
    assert (g["supply_min"], g["supply_max"]) == (2.0, 3.6)


@pytest.mark.parametrize("kw", [
    dict(group_name="Drain", pin_type="power"),
    dict(group_name="Q1", pin_type="analog", supply_rail_name="VDS"),
    dict(group_name="Anode", pin_type=None),
])
def test_rating_guard_positives(kw):
    out, rep = run([group(example_pins=["D"], supply_abs_max=60.0, absolute_max_voltage=60.0, **kw)])
    g = out["pin_groups"][0]
    assert g["supply_abs_max"] is None and g["absolute_max_voltage"] is None
    assert rep["counts"]["rating_nulled"] >= 1


@pytest.mark.parametrize("text", ["Operating Voltage", "Supply Voltage", "VCC", "PH Switch Node",
                                  "BOOT Bootstrap Capacitor"])
def test_rating_guard_negatives(text):
    for key in ("group_name", "supply_rail_name", "applies_to"):
        assert V.rating_match({"pin_type": "power", key: text}) is None


def test_504_checks():
    gs = [group(group_name="VCC", pin_type="power", example_pins=None),
          group(group_name="IO", example_pins=["ALL PINS", "PA1", "all signal pins"])]
    out, rep = run(gs, default="VCC")
    assert out["default_group"] is None
    assert out["pin_groups"][0]["example_pins"] == [] and out["pin_groups"][1]["example_pins"] == ["PA1"]
    assert rep["counts"]["example_pins_blanket_dropped"] == 2
    out, _ = run([group()], default="MISSING")
    assert out["default_group"] is None
    out, _ = run([group()], default="IO")
    assert out["default_group"] == "IO"


# ── robustness ───────────────────────────────────────────────────────────────
def test_malformed_groups_pass_through(monkeypatch):
    out, rep = run(["junk", group(VIH_min=2.0, quotes=["not", "a", "dict"])])
    assert out["pin_groups"][0] == "junk" and rep["counts"]["malformed_groups"] == 1
    assert out["pin_groups"][1]["citations"]["VIH_min"]["match"] == "no-quote"
    out, rep = V.validate({"pin_groups": "nope"}, model_input=DOC, source_text=None, stem="x")
    assert out == {"pin_groups": "nope"} and rep["counts"]["malformed_groups"] == 1
    out, rep = V.validate(None, model_input=None, source_text=None, stem=None)
    assert rep["counts"]["malformed_groups"] == 1

    def boom(*a, **k):
        raise RuntimeError("bad")
    monkeypatch.setattr(V, "rule_a", boom)
    g = group(VIH_min=2.0, quotes={"VIH_min": "High-level input voltage VIH 2.0 V"})
    out, rep = run([g])
    assert out["pin_groups"][0]["quotes"] == g["quotes"]     # this stage left the group unchanged
    assert rep["counts"]["malformed_groups"] == 1 and rep["malformed"][0]["error"] == "RuntimeError: bad"


def test_report_identity():
    _, rep = run([group()])
    assert rep["validator_version"] == V.VALIDATOR_VERSION == "3"
    assert len(rep["validator_sha256"]) == 64


# ── STEP 4: run_extractor wiring ─────────────────────────────────────────────
class _StubImpl(extractors.ExtractorImpl):
    name = "stub_validator"
    extractor_tag = "stub"
    input_path = "stub"
    model = "stub-model"

    def available(self):
        return True

    def build_model_input(self, ctx):
        ctx.source_text = DOC
        return DOC

    def extract(self, model_input, ctx):
        return {"pin_groups": [group(VIH_min=2.0, quotes={"VIH_min": "High-level input voltage VIH 2.0 V"})],
                "default_group": "IO"}


def test_run_extractor_stamps_citations_and_validation(tmp_path):
    pdf = tmp_path / "FOO123.pdf"
    pdf.write_bytes(b"%PDF-1.4 fake\n" * 50)
    dest = tmp_path / "out_pin_groups.json"
    ctx = extractors.PartContext(part_number="FOO123", pdf_path=str(pdf))
    ret = extractors.run_extractor(_StubImpl(), ctx, dry_run_to=str(dest))
    cache = json.loads(dest.read_text())
    g = cache["pin_groups"][0]
    assert g["citations"]["VIH_min"]["match"] == "verbatim" and "quotes" not in g
    assert ret["pin_groups"][0]["citations"] == g["citations"]
    val = cache["provenance"]["validation"]
    assert val["stem"] == "foo123" and val["validator_sha256"] == V.VALIDATOR_SHA256
    assert val["match"]["verbatim"] == 1
    assert "validation" not in json.dumps(cache["provenance"].get("extractor_fingerprint", {}))
    assert r3 is not None


# ── TODO-531 W3: a bare-number _expr moved by F4 is then cited and rule-checked ──
def test_f4_bare_moved_value_is_cited_and_rule_checked():
    row = "Output high voltage VOH IOH = -4 mA 1.24 V"           # a one-row table: two numbers, no header
    out, rep = run([group(group_name="OUT", pin_type="digital_output", example_pins=["1|Q"],
                          VOH_min_expr="1.24", quotes={"VOH_min_expr": row})], doc=row)
    g = out["pin_groups"][0]
    assert g["VOH_min"] == 1.24 and "VOH_min_expr" not in g
    assert rep["counts"]["expr_bare_moved"] == 1
    assert g["citations"]["VOH_min"]["match"] == "verbatim"
    assert g["citations"]["VOH_min"]["quote"] == row
    assert [(x["field"], x["outcome"]) for x in rep["f_outcomes"]] == [("VOH_min", "UNDECIDABLE")]
